{
    "single_choice_questions": [
        {
            "question": "Which inspection method should you use first to get a summary of column types and non-null counts in a new DataFrame?",
            "options": ["df.info()", "df.describe()", "df.shape", "df.head()"],
            "correct_option": 0,
            "explanation": "df.info() summarizes column data types and non-null counts, making it the go-to first check for a new dataset. df.describe() gives quick statistics, df.head() previews rows, and df.shape only returns the (rows, columns) tuple."
        },
        {
            "question": "Which line of code ranks regions by total revenue in a single readable, idiomatic Pandas chain?",
            "options": [
                "df.groupby(\"region\")[\"sales\"].sum().sort_values(ascending=False)",
                "df.sort_values(\"sales\").groupby(\"region\").sum()",
                "df[\"sales\"].groupby().sum(\"region\").sort()",
                "df.pivot_table(\"region\").sort_values(\"sales\")"
            ],
            "correct_option": 0,
            "explanation": "The document shows this exact chaining pattern: groupby splits rows by region, sum aggregates sales per group, and sort_values(ascending=False) ranks them. The other options misuse the groupby or pivot_table API."
        },
        {
            "question": "When presenting results to an executive audience, what does the document recommend leading with?",
            "options": [
                "The decision the data supports, using a ranked bar chart with a headline takeaway in the title",
                "A comprehensive dashboard requiring interpretation by the audience",
                "The full data-quality audit before any findings are shown",
                "An annotated chart showing every data point in the analysis"
            ],
            "correct_option": 0,
            "explanation": "The document advises leading with the decision the data supports, keeping one message per visual, annotating only key points, and preferring a ranked bar chart with a headline takeaway (e.g., 'West region leads Q3 sales by 18%') over dashboards that require interpretation."
        }
    ]
}
